import numpy as np
A=np.array(demo_in); O=np.array(demo_out)
shape={(0,0),(0,1),(1,2)}
def canon_transform(points):
    pts=list(points); forms=[]
    # dihedral transformations over coords x=row y=col
    for flip in [1,-1]:
        for k in range(4):
            ps=[]
            for r,c in pts:
                x,y=r,flip*c
                for _ in range(k): x,y=y,-x
                ps.append((x,y))
            mr=min(x for x,y in ps); mc=min(y for x,y in ps)
            forms.append(frozenset((x-mr,y-mc) for x,y in ps))
    return set(forms)
forms=canon_transform(shape)
marks=set()
for sh in forms:
    H=max(r for r,c in sh)+1; W=max(c for r,c in sh)+1
    for r in range(A.shape[0]-H+1):
